// Get the input configuration
let config = input.config();
let id = Number(config.id); // Convert to number to match the field type

// Get the table
let table = base.getTable('Workspace IDs');

// Query all records from the table
let query = await table.selectRecordsAsync();

// Find the record where the "ID" field matches our input
let matchingRecord = query.records.find(record => {
    return record.getCellValue('ID') === id;
});

// Output the result
if (matchingRecord) {
    let emailBisonAPI = matchingRecord.getCellValue('EmailBison API');
    output.set('emailBisonAPI', emailBisonAPI);
    console.log(`EmailBison API: ${emailBisonAPI}`);
} else {
    console.log(`No record found with ID: ${id}`);
    output.set('emailBisonAPI', null);
}

// OOO new-email sender v4. Future sends only; durable intent + exact receipt reconciliation.
const cfg = input.config();
const RECORD_ID = String(cfg.recordId || '');
const SENDER_EMAIL_ID = String(cfg.senderEmailId || '');
const API_TOKEN = String(cfg.api_key || '');
const API_ROOT = 'https://send.dulcy.io/api';
const table = base.getTable('Emails');
const eventsTable = base.getTable('Dulcy Reply Agent Events');

const SUBJECT = 'Back to work?';
// Keep the transport source ASCII-only so Airtable cannot corrupt the punctuation on paste/save.
const BODY_TEMPLATE = `
  <p>Hey {{first_name}},</p>
  <br>
  <p>You mentioned you would be back by this time &ndash; I reached out a couple days ago.</p>
  <br>
  <p>Hopefully we can catch up. Did you get a chance to look at my previous message?</p>
  <br>
  <p>Cheers</p>
  <br>
`;

function address(value) {
  if (value && typeof value === 'object') return address(value.address || value.email_address || value.email || '');
  const text = String(value || '').trim().toLowerCase();
  const angle = text.match(/<([^<>]+)>/);
  return (angle ? angle[1] : text).trim();
}

function validEmail(value) {
  return /^[^\s<>@]+@[^\s<>@]+\.[^\s<>@]+$/.test(value);
}

function repairKnownMojibake(value) {
  return String(value || '')
    .replace(/\u00e2\u0080\u0093/g, '\u2013')
    .replace(/\u00e2\u0080\u0094/g, '\u2014')
    .replace(/\u00e2\u0080\u0098/g, '\u2018')
    .replace(/\u00e2\u0080\u0099/g, '\u2019')
    .replace(/\u00c2\u00a0/g, ' ');
}

function decodeEntities(value) {
  const names = { amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: ' ', ndash: '\u2013', mdash: '\u2014' };
  return repairKnownMojibake(value).replace(/&(#x[0-9a-f]+|#\d+|[a-z]+);/gi, (all, key) => {
    if (key[0] === '#') {
      const code = key[1].toLowerCase() === 'x' ? parseInt(key.slice(2), 16) : parseInt(key.slice(1), 10);
      return Number.isSafeInteger(code) && code > 0 && code <= 0x10ffff ? String.fromCodePoint(code) : all;
    }
    return names[key.toLowerCase()] ?? all;
  });
}

function canonicalText(value) {
  return decodeEntities(String(value || '')
    .replace(/<(script|style)\b[^>]*>[\s\S]*?<\/\1\s*>/gi, '')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/(?:p|div|li|tr|h[1-6]|blockquote)\s*>/gi, '\n')
    .replace(/<li\b[^>]*>/gi, '- ')
    .replace(/<[^>]*>/g, ''))
    .replace(/\r\n?/g, '\n')
    .replace(/[ \t]+\n/g, '\n')
    .replace(/\n[ \t]+/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

function hash(value) {
  let result = 2166136261;
  for (const character of String(value)) {
    result ^= character.charCodeAt(0);
    result = Math.imul(result, 16777619);
  }
  return (result >>> 0).toString(16).padStart(8, '0');
}

function eventValue(record, field) {
  return typeof record?.getCellValue === 'function' ? record.getCellValue(field) : record?.[field];
}

function parsePayload(record) {
  const raw = String(eventValue(record, 'Payload JSON') || '');
  if (!raw) return null;
  try { return JSON.parse(raw); }
  catch { throw new Error(`Malformed OOO safety event ${String(record?.id || '')}`); }
}

function explicitTime(raw) {
  if (typeof raw !== 'string' || !/(?:Z|[+-]\d{2}:?\d{2}|\b(?:UT|UTC|GMT))\s*(?:\([^)]*\))?$/i.test(raw.trim())) return null;
  const millis = Date.parse(raw);
  return Number.isFinite(millis) ? new Date(millis).toISOString() : null;
}

async function requestJson(url, options = {}) {
  const response = await fetch(url, {
    ...options,
    headers: {
      Authorization: `Bearer ${API_TOKEN}`,
      'Content-Type': 'application/json',
      ...(options.headers || {}),
    },
  });
  const raw = await response.text();
  let payload = {};
  if (raw) {
    try { payload = JSON.parse(raw); }
    catch { throw new Error(`EmailBison returned non-JSON HTTP ${response.status}`); }
  }
  if (!response.ok || payload?.error || payload?.success === false) {
    throw new Error(`EmailBison request failed with HTTP ${response.status}`);
  }
  return payload;
}

function rowsFrom(payload) {
  if (Array.isArray(payload?.data)) return payload.data;
  if (Array.isArray(payload?.data?.data)) return payload.data.data;
  if (Array.isArray(payload?.records)) return payload.records;
  return [];
}

async function authoritativeAccounts() {
  const accounts = [];
  for (let page = 1; page <= 100; page += 1) {
    const payload = await requestJson(`${API_ROOT}/sender-emails?per_page=100&page=${page}`);
    accounts.push(...rowsFrom(payload));
    const meta = payload?.meta || payload?.data?.meta || {};
    const current = Number(meta.current_page || page);
    const last = Number(meta.last_page || current);
    const next = payload?.next_page_url || payload?.links?.next || meta.next_page_url;
    if (!next && current >= last) return accounts;
    if (!next && !Number.isFinite(last)) throw new Error('Sender account pagination is ambiguous');
  }
  throw new Error('Sender account pagination exceeded the safety limit');
}

function confirmedSend(payload) {
  const reply = payload?.data?.reply || payload?.data || {};
  const id = String(reply.id || reply.uuid || '');
  const status = String(reply.folder || reply.status || '').toLowerCase();
  const sentAt = explicitTime(reply.sent_at)
    || explicitTime(reply.date_sent)
    || (String(reply.type || '').toLowerCase() === 'outgoing email' ? explicitTime(reply.date_received) : null);
  if (!id || !['sent', 'delivered'].includes(status) || !sentAt || Date.parse(sentAt) > Date.now() + 60000) {
    throw new Error('Submission is unconfirmed or queued. Do not mark sent or retry automatically; reconcile by provider message ID.');
  }
  return { id, sentAt };
}

async function readSafetyEvents() {
  const result = await eventsTable.selectRecordsAsync({ fields: ['Event Key', 'Reply ID', 'Occurred At', 'Payload JSON'] });
  return Array.isArray(result?.records) ? result.records : [];
}

function conversationAddresses(value) {
  return [...new Set(String(value || '').toLowerCase().match(/[^\s:<>@]+@[^\s:<>@]+\.[^\s:<>@]+/g) || [])];
}

function exactConfirmedReceipts(rows, expected) {
  const matches = [];
  const conflicts = [];
  for (const row of rows) {
    const payload = parsePayload(row);
    if (!payload || payload.version !== 1 || String(payload.recordId || '') !== expected.recordId) continue;
    if (payload.provider !== 'emailbison' || payload.direction !== 'outbound') continue;
    if (canonicalText(payload.body) !== expected.body) continue;

    const binding = payload.receiptBinding || {};
    const subject = String(binding.subject || payload.subject || '');
    const senderAddress = address(binding.senderAddress || payload.sender);
    const senderEmailId = String(binding.senderEmailId || '');
    const to = [...new Set((Array.isArray(binding.to) ? binding.to : []).map(address).filter(validEmail))];
    const cc = [...new Set((Array.isArray(binding.cc) ? binding.cc : []).map(address).filter(validEmail))];
    const bcc = [...new Set((Array.isArray(binding.bcc) ? binding.bcc : []).map(address).filter(validEmail))];
    const legacyParticipants = conversationAddresses(payload.conversation);
    const clock = explicitTime(payload.clock?.iso);
    const messageId = String(payload.messageId || '');
    const key = `history:v1:emailbison:${expected.workspace}:${String(payload.conversation || '')}:${messageId}`;
    const eventKey = String(eventValue(row, 'Event Key') || '');
    const replyId = String(eventValue(row, 'Reply ID') || '');
    const participantMatch = to.length
      ? to.length === 1 && to[0] === expected.recipient
      : legacyParticipants.length === 2
        && legacyParticipants.includes(expected.recipient)
        && legacyParticipants.includes(expected.senderAddress);
    const exact =
      String(payload.workspace || '') === expected.workspace
      && senderAddress === expected.senderAddress
      && (!senderEmailId || senderEmailId === expected.senderEmailId)
      && (!subject || subject === SUBJECT)
      && participantMatch
      && cc.length === 0
      && bcc.length === 0
      && messageId
      && clock
      && ['Sent', 'Provider time'].includes(String(payload.clock?.kind || ''))
      && payload.key === key
      && eventKey === key
      && (!replyId || replyId === messageId);
    if (!exact) {
      conflicts.push(String(row?.id || eventKey || messageId || 'unknown'));
      continue;
    }
    matches.push({ key, messageId, fingerprint: String(payload.fingerprint || ''), sentAt: clock });
  }
  if (conflicts.length) throw new Error(`OOO-like provider receipt has a mismatched workspace, sender, recipient, or durable identity: ${conflicts.join(', ')}`);
  const unique = new Map();
  for (const match of matches) {
    const prior = unique.get(match.key);
    if (prior && prior.fingerprint !== match.fingerprint) throw new Error(`Conflicting duplicate OOO receipt ${match.key}`);
    unique.set(match.key, prior || match);
  }
  if (unique.size > 1) throw new Error('Multiple distinct confirmed OOO sends require human reconciliation; no retry or status change was made');
  return [...unique.values()];
}

function verifiedIntent(rows, intentKey, expected) {
  const found = rows.filter(row => String(eventValue(row, 'Event Key') || '') === intentKey);
  if (!found.length) return null;
  if (found.length !== 1) throw new Error('Duplicate OOO send intents detected; no message was sent');
  const payload = parsePayload(found[0]);
  const exact = payload?.version === 1
    && payload?.kind === 'ooo-send-intent'
    && payload?.recordId === expected.recordId
    && payload?.workspace === expected.workspace
    && payload?.senderEmailId === expected.senderEmailId
    && payload?.senderAddress === expected.senderAddress
    && payload?.recipient === expected.recipient
    && payload?.subject === SUBJECT
    && payload?.bodyFingerprint === expected.bodyFingerprint;
  if (!exact) throw new Error('OOO send intent identity mismatch; no message was sent');
  return { row: found[0], payload };
}

async function main() {
  if (!/^rec[a-zA-Z0-9]{14,}$/.test(RECORD_ID) || !/^\d+$/.test(SENDER_EMAIL_ID) || !API_TOKEN) {
    throw new Error('Missing or invalid record, sender, or API identity');
  }
  const record = await table.selectRecordAsync(RECORD_ID);
  if (!record) throw new Error('Record not found');

  if (record.getCellValue('OOO - Subsequence Email Sent') === true) {
    output.set('sendSkipped', true);
    output.set('skipReason', 'OOO send is already confirmed');
    return;
  }

  const firstName = String(record.getCellValue('OOO - First Name') || 'there').trim();
  const recipient = address(record.getCellValue('Leads Email'));
  const workspace = String(record.getCellValue('Workspace ID (Bison)') || '');
  if (!validEmail(recipient)) throw new Error('Missing or invalid authoritative external recipient');
  if (!/^\d+$/.test(workspace)) throw new Error('Missing authoritative EmailBison workspace identity');

  const senderPayload = await requestJson(`${API_ROOT}/sender-emails/${encodeURIComponent(SENDER_EMAIL_ID)}`);
  const sender = senderPayload?.data;
  const senderAddress = address(sender);
    const senderWorkspaces = [sender?.workspace_id, sender?.team_id, sender?.workspace?.id]
    .filter(value => value !== undefined && value !== null && String(value).trim() !== '')
    .map(value => String(value).trim());
  if (!sender || String(sender.id) !== SENDER_EMAIL_ID || !validEmail(senderAddress)) {
    throw new Error('Authoritative sender account unavailable or mismatched');
  }
    if (senderWorkspaces.some(value => value !== workspace)) throw new Error('Authoritative sender belongs to a different workspace');

  const accounts = await authoritativeAccounts();
  const internalAddresses = new Set(accounts.map(address).filter(validEmail));
  internalAddresses.add(senderAddress);
  if (internalAddresses.has(recipient)) throw new Error('Recipient is the sender or a known sender alias');

  const message = BODY_TEMPLATE.replace('{{first_name}}', firstName);
  const expected = {
    recordId: RECORD_ID,
    workspace,
    senderEmailId: SENDER_EMAIL_ID,
    senderAddress,
    recipient,
    body: canonicalText(message),
  };
  expected.bodyFingerprint = hash(`${SUBJECT}\n${expected.body}`);
  const intentKey = `ooo-send:v1:${workspace}:${RECORD_ID}:${SENDER_EMAIL_ID}:${hash(recipient)}:${expected.bodyFingerprint}`;
  let safetyRows = await readSafetyEvents();

  const receipts = exactConfirmedReceipts(safetyRows, expected);
  if (receipts.length === 1) {
    await table.updateRecordAsync(RECORD_ID, { 'OOO - Subsequence Email Sent': true });
    output.set('sendReconciled', true);
    output.set('providerMessageId', receipts[0].messageId);
    output.set('sentAt', receipts[0].sentAt);
    return;
  }

  const existingIntent = verifiedIntent(safetyRows, intentKey, expected);
  if (existingIntent) {
    const confirmedAt = explicitTime(existingIntent.payload.providerSentAt);
    if (existingIntent.payload.state === 'confirmed' && existingIntent.payload.providerSubmissionId && confirmedAt) {
      await table.updateRecordAsync(RECORD_ID, { 'OOO - Subsequence Email Sent': true });
      output.set('sendReconciled', true);
      output.set('providerMessageId', existingIntent.payload.providerSubmissionId);
      output.set('sentAt', confirmedAt);
      return;
    }
    throw new Error('An OOO send attempt already exists without a confirmed provider receipt. Do not send or retry automatically.');
  }

  const createdAt = new Date().toISOString();
  const intentPayload = {
    version: 1,
    kind: 'ooo-send-intent',
    state: 'pending',
    recordId: RECORD_ID,
    workspace,
    senderEmailId: SENDER_EMAIL_ID,
    senderAddress,
    recipient,
    subject: SUBJECT,
    bodyFingerprint: expected.bodyFingerprint,
    createdAt,
  };
  const intentRecordId = await eventsTable.createRecordAsync({
    'Event Key': intentKey,
    'Occurred At': createdAt,
    'Payload JSON': JSON.stringify(intentPayload),
  });
  safetyRows = await readSafetyEvents();
  const durableIntent = verifiedIntent(safetyRows, intentKey, expected);
  if (!durableIntent || String(durableIntent.row.id || '') !== String(intentRecordId || '')) {
    throw new Error('OOO send intent could not be uniquely serialized; no message was sent');
  }

  const result = await requestJson(`${API_ROOT}/replies/new`, {
    method: 'POST',
    body: JSON.stringify({
      subject: SUBJECT,
      message,
      sender_email_id: Number(SENDER_EMAIL_ID),
      use_dedicated_ips: true,
      content_type: 'html',
      to_emails: [{ name: firstName, email_address: recipient }],
    }),
  });

  let confirmation;
  try {
    confirmation = confirmedSend(result);
  } catch (error) {
    const reply = result?.data?.reply || result?.data || {};
    const providerSubmissionId = String(reply.id || reply.uuid || '');
    const providerStatus = String(reply.folder || reply.status || 'unknown');
    await eventsTable.updateRecordAsync(intentRecordId, {
      'Reply ID': providerSubmissionId,
      'Payload JSON': JSON.stringify({ ...intentPayload, state: 'submitted-unconfirmed', providerSubmissionId, providerStatus }),
    });
    throw error;
  }

  await eventsTable.updateRecordAsync(intentRecordId, {
    'Reply ID': confirmation.id,
    'Occurred At': confirmation.sentAt,
     'Payload JSON': JSON.stringify({
      ...intentPayload,
      state: 'confirmed',
      providerSubmissionId: confirmation.id,
      providerSentAt: confirmation.sentAt,
    }),
  });
  await table.updateRecordAsync(RECORD_ID, { 'OOO - Subsequence Email Sent': true });
  output.set('providerMessageId', confirmation.id);
  output.set('sentAt', confirmation.sentAt);
  output.set('intentKey', intentKey);
}

await main();
